// DP sketch for distinct-count blocks
let n = A.length;
let C = Array.from({length:n}, ()=>Array(n).fill(0));
for (let L=0; L<n; L++) {
  let seen = new Map();
  let d = 0;
  for (let R=L; R<n; R++) {
    if (!seen.has(A[R])) { seen.set(A[R],1); d++; }
    C[L][R] = d;
  }
}
let dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
let par = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
